package es.educacion.orm;
import es.educacion.orm.config.EntityManagerFactories; import es.educacion.orm.model.Vehiculo; import es.educacion.orm.orm.VehiculoOrmRepository; import es.educacion.orm.repository.IVehiculoRepository; import jakarta.persistence.EntityManagerFactory; import org.junit.jupiter.api.*; import org.junit.jupiter.api.io.TempDir; import java.nio.file.Path; import static org.junit.jupiter.api.Assertions.*;
class VehiculoOrmRepositoryTest { @TempDir Path temp; @Test void crudCompleto(){try(EntityManagerFactory emf=EntityManagerFactories.forTest(temp.resolve("vehiculos.db"))){IVehiculoRepository r=new VehiculoOrmRepository(emf);r.create(new Vehiculo("1234abc","Toyota","Corolla",2022));assertEquals("1234ABC",r.findById("1234ABC").orElseThrow().matricula());assertTrue(r.update(new Vehiculo("1234ABC","Toyota","Corolla",2024)));assertEquals(2024,r.findById("1234ABC").orElseThrow().anio());assertTrue(r.delete("1234ABC"));assertTrue(r.findAll().isEmpty());}} }